      designer: ctx.projectDesigner || ctx.designer || "",
      description: ctx.projectDescription || ctx.description || "",
      w: ctx.sW || ctx.w,
      h: ctx.sH || ctx.h,
      pattern: pattern,
      palette: pal,
      specialtyStitches:ctx.specialtyStitches||[],
      partialStitches: partialEntries,
      bsLines: ctx.bsLines || [],
      // French knots; only the Workshop print theme draws them.
      knots: ctx.knots && ctx.knots.length ? ctx.knots.map(function (k) { return { x: k.x, y: k.y, id: k.id, rgb: k.rgb }; }) : undefined,
