      pageSize: "auto",
      marginsMm: 12,
      stitchesPerPage: stPerPg,
      chartModes: modes,
      overlap: true,
      includeCover: true,
      includeInfo: true,
      includeIndex: true,
      miniLegend: true,
      branding: readBranding(),
